-- Generated by Supabase CLI migration new target_inventory_restoration_tombstones.
-- Immutable purchase receipts remain intact; only their active inventory changes.
BEGIN;
SELECT pg_advisory_xact_lock(991101);
DO $guard$ BEGIN
  IF (SELECT md5(prosrc) FROM pg_proc WHERE oid='public.target_shop_rpc(text,text,jsonb)'::regprocedure)
      IS DISTINCT FROM '85f256b4d1c758633806ac374bb4ef9f' OR
    (SELECT md5(prosrc) FROM pg_proc WHERE oid='target_private.wallet_snapshot(uuid)'::regprocedure)
      IS DISTINCT FROM '9bb62e2fbe1a817d2d6e9202baf193e7' OR
    (SELECT md5(prosrc) FROM pg_proc WHERE oid='target_private.wallet_finance_projection(timestamptz)'::regprocedure)
      IS DISTINCT FROM 'cfff50631cbabc7a51367106036e94f3' THEN
    RAISE EXCEPTION 'Inventory accounting changed; review the tombstone migration again'; END IF;
END $guard$;

CREATE TABLE target_private.inventory_restoration_events (
  reset_id text PRIMARY KEY CHECK(reset_id ~ '^[a-zA-Z0-9_-]{1,80}$'),
  cutoff_at timestamptz NOT NULL CHECK(isfinite(cutoff_at)),
  base_wallet_reset_id text NOT NULL REFERENCES target_private.wallet_restoration_events(reset_id),
  prepared_at timestamptz NOT NULL CHECK(isfinite(prepared_at)),
  member_count integer NOT NULL CHECK(member_count BETWEEN 0 AND 500),
  voided_draw_count integer NOT NULL CHECK(voided_draw_count BETWEEN 0 AND 100000000),
  additional_refund bigint NOT NULL CHECK(additional_refund BETWEEN 0 AND 10000000000000 AND additional_refund%100000=0),
  before_inventory_sha256 text NOT NULL CHECK(before_inventory_sha256 ~ '^[a-f0-9]{64}$'),
  created_at timestamptz NOT NULL DEFAULT clock_timestamp() CHECK(isfinite(created_at)),
  CHECK(cutoff_at<=prepared_at AND prepared_at<=created_at)
);
CREATE TABLE target_private.inventory_voids (
  member_id uuid NOT NULL,
  request_id uuid NOT NULL,
  reset_id text NOT NULL REFERENCES target_private.inventory_restoration_events(reset_id),
  item_type text NOT NULL CHECK(item_type IN ('sticker','frame')),
  item_id text NOT NULL,
  cost integer NOT NULL CHECK(cost=100000),
  drawn_at timestamptz NOT NULL CHECK(isfinite(drawn_at)),
  wallet_refund_reset_id text REFERENCES target_private.wallet_restoration_events(reset_id),
  additional_refund bigint NOT NULL CHECK(additional_refund IN (0,100000)),
  created_at timestamptz NOT NULL DEFAULT clock_timestamp() CHECK(isfinite(created_at)),
  PRIMARY KEY(member_id,request_id),
  FOREIGN KEY(member_id,request_id) REFERENCES target_private.item_draws(member_id,request_id),
  CHECK(additional_refund=CASE WHEN wallet_refund_reset_id IS NULL THEN cost ELSE 0 END)
);
CREATE INDEX inventory_voids_reset ON target_private.inventory_voids(reset_id);
CREATE TABLE target_private.inventory_restorations (
  reset_id text NOT NULL REFERENCES target_private.inventory_restoration_events(reset_id),
  member_id uuid NOT NULL REFERENCES target_private.profiles(member_id),
  before_state jsonb NOT NULL CHECK(jsonb_typeof(before_state)='object'),
  restored_state jsonb NOT NULL CHECK(jsonb_typeof(restored_state)='object'),
  voided_draw_count integer NOT NULL CHECK(voided_draw_count BETWEEN 0 AND 100000000),
  additional_refund bigint NOT NULL CHECK(additional_refund BETWEEN 0 AND 10000000000000 AND additional_refund%100000=0),
  created_at timestamptz NOT NULL DEFAULT clock_timestamp() CHECK(isfinite(created_at)),
  PRIMARY KEY(reset_id,member_id),
  CHECK((restored_state->>'walletRevision')::bigint=(before_state->>'walletRevision')::bigint+1),
  CHECK((before_state->>'spent')::bigint-(restored_state->>'spent')::bigint=additional_refund),
  CHECK((before_state->>'totalIncome')::bigint=(restored_state->>'totalIncome')::bigint)
);
ALTER TABLE target_private.inventory_restoration_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE target_private.inventory_voids ENABLE ROW LEVEL SECURITY;
ALTER TABLE target_private.inventory_restorations ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE target_private.inventory_restoration_events,target_private.inventory_voids,target_private.inventory_restorations
  FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION target_private.protect_inventory_history()
RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN RAISE EXCEPTION 'Inventory restoration records are permanent' USING ERRCODE='42501'; END $$;
CREATE TRIGGER inventory_restoration_event_permanent BEFORE UPDATE OR DELETE ON target_private.inventory_restoration_events
  FOR EACH ROW EXECUTE FUNCTION target_private.protect_inventory_history();
CREATE TRIGGER inventory_void_permanent BEFORE UPDATE OR DELETE ON target_private.inventory_voids
  FOR EACH ROW EXECUTE FUNCTION target_private.protect_inventory_history();
CREATE TRIGGER inventory_restoration_permanent BEFORE UPDATE OR DELETE ON target_private.inventory_restorations
  FOR EACH ROW EXECUTE FUNCTION target_private.protect_inventory_history();

CREATE FUNCTION target_private.gacha_receipts(p_member uuid DEFAULT NULL)
RETURNS TABLE(member_id uuid,request_id uuid,item_type text,item_id text,cost integer,drawn_at timestamptz)
LANGUAGE sql STABLE SET search_path=pg_catalog AS $$
  SELECT member_id,request_id,'sticker'::text,sticker_id,cost,created_at FROM target_private.sticker_draws
    WHERE p_member IS NULL OR member_id=p_member
  UNION ALL SELECT member_id,request_id,item_type,coalesce(sticker_id,frame_id),cost,created_at FROM target_private.item_draws
    WHERE p_member IS NULL OR member_id=p_member;
$$;
CREATE FUNCTION target_private.active_gacha_receipts(p_member uuid DEFAULT NULL)
RETURNS TABLE(member_id uuid,request_id uuid,item_type text,item_id text,cost integer,drawn_at timestamptz)
LANGUAGE sql STABLE SET search_path=pg_catalog AS $$
  SELECT r.* FROM target_private.gacha_receipts(p_member) r
    WHERE NOT EXISTS(SELECT 1 FROM target_private.inventory_voids v WHERE v.member_id=r.member_id AND v.request_id=r.request_id);
$$;
CREATE FUNCTION target_private.receipt_wallet_refund(p_member uuid,p_request uuid)
RETURNS text LANGUAGE sql STABLE SET search_path=pg_catalog AS $$
  SELECT e.reset_id FROM target_private.gacha_receipts(p_member) d
    JOIN target_private.wallet_restorations r ON r.member_id=d.member_id
    JOIN target_private.wallet_restoration_events e USING(reset_id)
    WHERE d.request_id=p_request AND d.drawn_at>=e.cutoff_at AND d.drawn_at<e.prepared_at AND r.spent_refund>0
      AND NOT EXISTS(SELECT 1 FROM target_private.inventory_voids v
        WHERE v.member_id=d.member_id AND v.request_id=d.request_id AND v.additional_refund>0)
    ORDER BY e.created_at,e.reset_id LIMIT 1;
$$;
CREATE FUNCTION target_private.validate_inventory_void()
RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE d target_private.item_draws%rowtype;
BEGIN
  SELECT * INTO STRICT d FROM target_private.item_draws WHERE member_id=NEW.member_id AND request_id=NEW.request_id;
  IF (NEW.item_type,NEW.item_id,NEW.cost,NEW.drawn_at) IS DISTINCT FROM(d.item_type,coalesce(d.sticker_id,d.frame_id),d.cost,d.created_at) THEN
    RAISE EXCEPTION 'Inventory tombstone does not match its immutable purchase' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER inventory_void_receipt BEFORE INSERT ON target_private.inventory_voids
  FOR EACH ROW EXECUTE FUNCTION target_private.validate_inventory_void();
CREATE FUNCTION target_private.enforce_active_gacha_protocol()
RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN
  IF EXISTS(SELECT 1 FROM target_private.inventory_restoration_events) AND
    current_setting('target.gacha_inventory_protocol',true) IS DISTINCT FROM 'active-v1' THEN
    RAISE EXCEPTION 'Active inventory purchase protocol required' USING ERRCODE='42501'; END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER target_active_gacha_protocol BEFORE INSERT ON target_private.item_draws
  FOR EACH ROW EXECUTE FUNCTION target_private.enforce_active_gacha_protocol();

CREATE OR REPLACE FUNCTION target_private.wallet_snapshot(p_member uuid)
RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
  WITH receipts AS(SELECT * FROM target_private.gacha_receipts(p_member)),
  quantities AS(SELECT item_type,item_id,count(*)::integer quantity FROM target_private.active_gacha_receipts(p_member) GROUP BY item_type,item_id),
  refunds AS(SELECT coalesce((SELECT sum(spent_refund) FROM target_private.wallet_restorations WHERE member_id=p_member),0)
      +coalesce((SELECT sum(additional_refund) FROM target_private.inventory_voids WHERE member_id=p_member),0) amount),
  voids AS(SELECT count(*)::integer amount FROM target_private.inventory_voids WHERE member_id=p_member)
  SELECT jsonb_build_object('balance',p.total_points-p.spent_points,'totalIncome',p.total_points,'spent',p.spent_points,'walletRevision',p.wallet_revision,
    'mapSpent',coalesce((SELECT sum(cost) FROM target_private.map_purchases WHERE member_id=p_member),0)+coalesce((SELECT sum(cost) FROM target_private.territory_orders WHERE member_id=p_member),0),
    'price',100000,'catalogVersion',3,'catalogSize',17,'frameCatalogSize',33,'duplicatesAllowed',true,
    'drawCount',(SELECT count(*)::integer FROM receipts),'legacyDiscountedDraws',(SELECT count(*)::integer FROM receipts WHERE cost=10000),
    'frameOdds',jsonb_build_object('common',62,'rare',25,'epic',10,'legendary',3),
    'ownedStickers',coalesce((SELECT jsonb_agg(c.id ORDER BY c.ordinal) FROM target_private.sticker_catalog c JOIN quantities q ON q.item_type='sticker' AND q.item_id=c.id),'[]'::jsonb),
    'stickerQuantities',coalesce((SELECT jsonb_agg(jsonb_build_object('id',c.id,'quantity',q.quantity) ORDER BY c.ordinal) FROM target_private.sticker_catalog c JOIN quantities q ON q.item_type='sticker' AND q.item_id=c.id),'[]'::jsonb),
    'ownedFrames',coalesce((SELECT jsonb_agg(c.id ORDER BY c.ordinal) FROM target_private.frame_catalog c JOIN quantities q ON q.item_type='frame' AND q.item_id=c.id),'[]'::jsonb),
    'frameQuantities',coalesce((SELECT jsonb_agg(jsonb_build_object('id',c.id,'quantity',q.quantity) ORDER BY c.ordinal) FROM target_private.frame_catalog c JOIN quantities q ON q.item_type='frame' AND q.item_id=c.id),'[]'::jsonb))
    ||CASE WHEN refunds.amount>0 THEN jsonb_build_object('refundedSpend',refunds.amount) ELSE '{}'::jsonb END
    ||CASE WHEN voids.amount>0 THEN jsonb_build_object('voidedDrawCount',voids.amount) ELSE '{}'::jsonb END
  FROM target_private.profiles p CROSS JOIN refunds CROSS JOIN voids WHERE p.member_id=p_member;
$$;

-- Preserve the complete existing public purchase boundary and RNG/price rules.
DO $shop$
DECLARE definition text; original text; old_stickers text; new_stickers text;
BEGIN
  SELECT pg_get_functiondef('public.target_shop_rpc(text,text,jsonb)'::regprocedure) INTO definition; original:=definition;
  definition:=replace(definition,'chosen_count integer; wait_seconds integer; new_bytes integer; quantity integer;',
    'chosen_count integer; wait_seconds integer; new_bytes integer; quantity integer; receipt_voided boolean:=false;');
  old_stickers:='FROM (SELECT sticker_id FROM target_private.sticker_draws WHERE member_id=member_uuid UNION ALL SELECT sticker_id FROM target_private.item_draws WHERE member_id=member_uuid AND item_type=''sticker'') d WHERE d.sticker_id=';
  new_stickers:='FROM target_private.active_gacha_receipts(member_uuid) d WHERE d.item_type=''sticker'' AND d.item_id=';
  IF (length(definition)-length(replace(definition,old_stickers,'')))/length(old_stickers)<>2 THEN
    RAISE EXCEPTION 'Unexpected historical sticker quantity branches'; END IF;
  definition:=replace(definition,old_stickers,new_stickers);
  definition:=replace(definition,'ELSE SELECT count(*)::integer INTO quantity FROM target_private.item_draws WHERE member_id=member_uuid AND frame_id=chosen_id; END IF;',
    'ELSE SELECT count(*)::integer INTO quantity FROM target_private.active_gacha_receipts(member_uuid) WHERE item_type=''frame'' AND item_id=chosen_id; END IF;');
  definition:=replace(definition,'chosen_id:=coalesce(saved.sticker_id,saved.frame_id); chosen_rarity:=',
    'receipt_voided:=EXISTS(SELECT 1 FROM target_private.inventory_voids WHERE member_id=member_uuid AND request_id=request_uuid); chosen_id:=coalesce(saved.sticker_id,saved.frame_id); chosen_rarity:=');
  definition:=replace(definition,'PERFORM set_config(''target.gacha_price_protocol'',''100000'',true); PERFORM set_config(''target.gacha_catalog_protocol'',''3'',true);',
    'PERFORM set_config(''target.gacha_inventory_protocol'',''active-v1'',true); PERFORM set_config(''target.gacha_price_protocol'',''100000'',true); PERFORM set_config(''target.gacha_catalog_protocol'',''3'',true);');
  definition:=replace(definition,'''quantity'',quantity)||'||chr(10)||'    CASE WHEN saved.item_type=',
    '''quantity'',quantity)||CASE WHEN receipt_voided THEN jsonb_build_object(''receiptVoided'',true) ELSE ''{}''::jsonb END||'||chr(10)||'    CASE WHEN saved.item_type=');
  IF definition=original OR position('receipt_voided boolean:=false;' IN definition)=0 OR
    position('jsonb_build_object(''receiptVoided'',true)' IN definition)=0 OR
    position('target.gacha_inventory_protocol' IN definition)=0 OR position('FROM target_private.item_draws WHERE member_id=member_uuid AND frame_id=chosen_id' IN definition)>0 THEN
    RAISE EXCEPTION 'Purchase inventory adaptation did not match the reviewed boundary'; END IF;
  EXECUTE definition;
END $shop$;

-- Spending corrections belong to the existing component projection exactly once.
DO $projection$
DECLARE definition text; old_value text; new_value text;
BEGIN
  SELECT pg_get_functiondef('target_private.wallet_finance_projection(timestamptz)'::regprocedure) INTO definition;
  old_value:='coalesce(x.amount,0)+coalesce(r.spent,0) spent';
  new_value:='coalesce(x.amount,0)+coalesce(r.spent,0)-coalesce((SELECT sum(i.additional_refund) FROM target_private.inventory_voids i WHERE i.member_id=p.member_id AND (p_cutoff IS NULL OR i.created_at<p_cutoff)),0) spent';
  IF (length(definition)-length(replace(definition,old_value,'')))/length(old_value)<>1 THEN
    RAISE EXCEPTION 'Unexpected financial spending projection'; END IF;
  EXECUTE replace(definition,old_value,new_value);
END $projection$;

CREATE FUNCTION target_private.restore_inventory(p_reset_id text,p_cutoff timestamptz,p_wallet_reset_id text)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE e target_private.inventory_restoration_events%rowtype; base target_private.wallet_restoration_events%rowtype;
  p target_private.profiles%rowtype; draw_value record; prepared timestamptz; before_states jsonb; before_value jsonb; after_value jsonb;
  members integer; draws integer; new_refund bigint; refund_for_member bigint; voids_for_member integer; audit_bytes bigint;
BEGIN
  IF p_reset_id IS NULL OR p_reset_id!~'^[a-zA-Z0-9_-]{1,80}$' OR p_cutoff IS NULL OR NOT isfinite(p_cutoff)
    OR p_cutoff>clock_timestamp() OR p_wallet_reset_id IS NULL THEN
    RAISE EXCEPTION 'Invalid inventory restoration metadata' USING ERRCODE='22023'; END IF;
  PERFORM pg_advisory_xact_lock(991101);
  PERFORM 1 FROM target_private.system_state WHERE singleton FOR UPDATE;
  LOCK TABLE target_private.profiles IN SHARE ROW EXCLUSIVE MODE;
  SELECT * INTO e FROM target_private.inventory_restoration_events WHERE reset_id=p_reset_id;
  IF FOUND THEN
    IF e.cutoff_at<>p_cutoff OR e.base_wallet_reset_id<>p_wallet_reset_id THEN
      RAISE EXCEPTION 'Inventory restoration ID has different metadata' USING ERRCODE='22023'; END IF;
    RETURN jsonb_build_object('resetId',e.reset_id,'cutoffAt',e.cutoff_at,'members',e.member_count,
      'voidedDraws',e.voided_draw_count,'additionalRefund',e.additional_refund,'replayed',true);
  END IF;
  SELECT * INTO base FROM target_private.wallet_restoration_events WHERE reset_id=p_wallet_reset_id;
  IF NOT FOUND OR base.cutoff_at<>p_cutoff THEN RAISE EXCEPTION 'Matching completed financial restoration is required' USING ERRCODE='23514'; END IF;
  prepared:=clock_timestamp();
  IF EXISTS(SELECT 1 FROM target_private.sticker_draws WHERE created_at>=p_cutoff) OR EXISTS(
    SELECT 1 FROM target_private.inventory_voids WHERE drawn_at<p_cutoff) THEN
    RAISE EXCEPTION 'Historical legacy or earlier inventory tombstones need a separate reviewed policy' USING ERRCODE='23514'; END IF;
  IF EXISTS(SELECT 1 FROM target_private.wallet_finance_projection(NULL) l JOIN target_private.profiles a USING(member_id)
    WHERE (a.total_points,a.spent_points,a.calculus_points,a.birthday_points,a.casino_net,a.calculus_forgiven_points)
      IS DISTINCT FROM(l.total_points,l.spent_points,l.calculus_points,l.birthday_points,l.casino_net,l.calculus_forgiven_points)) THEN
    RAISE EXCEPTION 'Current wallet components do not reconcile' USING ERRCODE='23514'; END IF;
  -- Aggregate financial refunds must identify the exact immutable receipt set.
  IF EXISTS(SELECT 1 FROM target_private.profiles a WHERE
    coalesce((SELECT sum(r.spent_refund) FROM target_private.wallet_restorations r WHERE r.member_id=a.member_id),0)<>
    coalesce((SELECT sum(r.cost) FROM target_private.gacha_receipts(a.member_id) r
      WHERE target_private.receipt_wallet_refund(r.member_id,r.request_id) IS NOT NULL),0)) THEN
    RAISE EXCEPTION 'Financial refund coverage cannot be assigned exactly to purchase receipts' USING ERRCODE='23514'; END IF;
  SELECT count(*) INTO members FROM target_private.profiles;
  SELECT count(*)::integer,coalesce(sum(CASE WHEN target_private.receipt_wallet_refund(d.member_id,d.request_id) IS NULL THEN d.cost ELSE 0 END),0)::bigint
    INTO draws,new_refund FROM target_private.item_draws d WHERE d.created_at>=p_cutoff
      AND NOT EXISTS(SELECT 1 FROM target_private.inventory_voids v WHERE v.member_id=d.member_id AND v.request_id=d.request_id);
  IF EXISTS(SELECT 1 FROM target_private.profiles a WHERE a.wallet_revision>=10000000000000 OR a.spent_points<
    coalesce((SELECT sum(d.cost) FROM target_private.item_draws d WHERE d.member_id=a.member_id AND d.created_at>=p_cutoff
      AND target_private.receipt_wallet_refund(d.member_id,d.request_id) IS NULL
      AND NOT EXISTS(SELECT 1 FROM target_private.inventory_voids v WHERE v.member_id=d.member_id AND v.request_id=d.request_id)),0)) THEN
    RAISE EXCEPTION 'Inventory refund or revision exceeds the current financial bounds' USING ERRCODE='23514'; END IF;
  SELECT coalesce(jsonb_object_agg(a.member_id::text,target_private.wallet_snapshot(a.member_id)),'{}'::jsonb)
    INTO before_states FROM target_private.profiles a;
  audit_bytes:=1024+members*16384+draws*768;
  UPDATE target_private.system_state SET logical_bytes=logical_bytes+audit_bytes WHERE singleton AND logical_bytes<=104857600-audit_bytes;
  IF NOT FOUND THEN RAISE EXCEPTION 'Inventory restoration audit exceeds capacity' USING ERRCODE='54000'; END IF;
  INSERT INTO target_private.inventory_restoration_events(reset_id,cutoff_at,base_wallet_reset_id,prepared_at,member_count,
    voided_draw_count,additional_refund,before_inventory_sha256)
    VALUES(p_reset_id,p_cutoff,p_wallet_reset_id,prepared,members,draws,new_refund,encode(sha256(convert_to(before_states::text,'UTF8')),'hex'));
  FOR draw_value IN SELECT d.* FROM target_private.item_draws d WHERE d.created_at>=p_cutoff
    AND NOT EXISTS(SELECT 1 FROM target_private.inventory_voids v WHERE v.member_id=d.member_id AND v.request_id=d.request_id)
    ORDER BY d.member_id,d.created_at,d.request_id LOOP
    INSERT INTO target_private.inventory_voids(member_id,request_id,reset_id,item_type,item_id,cost,drawn_at,wallet_refund_reset_id,additional_refund)
      SELECT draw_value.member_id,draw_value.request_id,p_reset_id,draw_value.item_type,coalesce(draw_value.sticker_id,draw_value.frame_id),draw_value.cost,draw_value.created_at,
        proof.reset_id,CASE WHEN proof.reset_id IS NULL THEN draw_value.cost ELSE 0 END
      FROM(SELECT target_private.receipt_wallet_refund(draw_value.member_id,draw_value.request_id) reset_id) proof;
  END LOOP;
  FOR p IN SELECT * FROM target_private.profiles ORDER BY member_id LOOP
    SELECT coalesce(sum(additional_refund),0),count(*)::integer INTO refund_for_member,voids_for_member
      FROM target_private.inventory_voids WHERE reset_id=p_reset_id AND member_id=p.member_id;
    before_value:=before_states->p.member_id::text;
    UPDATE target_private.profiles SET total_points=total_points,spent_points=spent_points-refund_for_member,updated_at=now()
      WHERE member_id=p.member_id;
    after_value:=target_private.wallet_snapshot(p.member_id);
    INSERT INTO target_private.inventory_restorations(reset_id,member_id,before_state,restored_state,voided_draw_count,additional_refund)
      VALUES(p_reset_id,p.member_id,before_value,after_value,voids_for_member,refund_for_member);
  END LOOP;
  IF EXISTS(SELECT 1 FROM target_private.active_gacha_receipts(NULL) WHERE drawn_at>=p_cutoff) OR EXISTS(
    SELECT 1 FROM target_private.wallet_finance_projection(NULL) l JOIN target_private.profiles a USING(member_id)
    WHERE (a.total_points,a.spent_points,a.calculus_points,a.birthday_points,a.casino_net,a.calculus_forgiven_points)
      IS DISTINCT FROM(l.total_points,l.spent_points,l.calculus_points,l.birthday_points,l.casino_net,l.calculus_forgiven_points)) THEN
    RAISE EXCEPTION 'Inventory restoration does not reconcile with active receipts and financial history' USING ERRCODE='23514'; END IF;
  RETURN jsonb_build_object('resetId',p_reset_id,'cutoffAt',p_cutoff,'members',members,'voidedDraws',draws,'additionalRefund',new_refund,'replayed',false);
END $$;
REVOKE ALL ON FUNCTION target_private.protect_inventory_history(),target_private.gacha_receipts(uuid),target_private.active_gacha_receipts(uuid),
  target_private.receipt_wallet_refund(uuid,uuid),target_private.validate_inventory_void(),target_private.enforce_active_gacha_protocol(),
  target_private.wallet_snapshot(uuid),target_private.wallet_finance_projection(timestamptz),target_private.restore_inventory(text,timestamptz,text)
  FROM PUBLIC,anon,authenticated,service_role;
COMMIT;
